function AppIcon({name,size=19,strokeWidth=1.8,...props}){const C=iconMap[name]||Sparkles;return <C size={size} strokeWidth={strokeWidth} aria-hidden="true" {...props}/>}

const nav=[["dashboard","dashboard","Dashboard"],["learn","learn","Learn from Video"],["knowledge","knowledge","Knowledge Base"],["chat","chat","AI Chat"],["summaries","summaries","Summaries"],["sources","sources","Learning Sources"],["history","history","History"],["profile","profile","Profile"],["settings","settings","Settings"]];
const prompts=["Explain a concept from my videos","Summarize my latest lesson","Find related topics","Create revision questions"];

function InlineMarkdown({text}){const parts=String(text||"").split(/(\*\*[^*]+\*\*|\*[^*]+\*|\x60[^\x60]+\x60)/g);return <>{parts.map((part,i)=>part.startsWith("**")&&part.endsWith("**")?<strong key={i}>{part.slice(2,-2)}</strong>:part.startsWith("*")&&part.endsWith("*")?<em key={i}>{part.slice(1,-1)}</em>:part.startsWith("\x60")&&part.endsWith("\x60")?<code key={i}>{part.slice(1,-1)}</code>:part)}</>}
function ResponseContent({content,pending}){if(pending)return <div className="thinking-status"><span className="thinking-dots"><i/><i/><i/></span><span>Generating your answer…</span><small>Using the available AI models</small></div>;
 const normalized=String(content||"").replace(/\\r/g,"\r").replace(/\\n/g,"\n").replace(/\r\n/g,"\n").replace(/\r/g,"\n");
 const lines=normalized.split("\n");const out=[];let code=[],inCode=false,list=[],listType="",table=[];
 const flushList=()=>{if(list.length){out.push(listType==="ol"?<ol key={"list"+out.length}>{list.map((x,i)=><li key={i}><InlineMarkdown text={x}/></li>)}</ol>:<ul key={"list"+out.length}>{list.map((x,i)=><li key={i}><InlineMarkdown text={x}/></li>)}</ul>);list=[];listType=""}};
 const flushTable=()=>{if(table.length){out.push(<div className="response-table-wrap" key={"table"+out.length}><table><tbody>{table.map((row,i)=><tr key={i}>{row.split("|").filter((x,j,a)=>!(j===0&&x.trim()==="")&&!(j===a.length-1&&x.trim()==="")).map((cell,j)=>i===0?<th key={j}><InlineMarkdown text={cell.trim()}/></th>:<td key={j}><InlineMarkdown text={cell.trim()}/></td>)}</tr>)}</tbody></table></div>);table=[]}};
 lines.forEach((raw,i)=>{const t=raw.trim();if(t.startsWith("\x60\x60\x60")){flushList();flushTable();if(inCode){out.push(<pre key={"code"+out.length}><code>{code.join("\n")}</code></pre>);code=[];inCode=false}else{inCode=true}return}if(inCode){code.push(raw);return}if(!t){flushList();flushTable();out.push(<div className="response-space" key={"space"+i}/>);return}if(t.startsWith("|")){flushList();if(!/^\s*\|?\s*:?-{3,}/.test(t))table.push(t);return}flushTable();if(/^#{1,6}\s/.test(t)){flushList();const level=t.match(/^#+/)[0].length;const text=t.slice(level).trim();out.push(level<=2?<h3 key={i}><InlineMarkdown text={text}/></h3>:<h4 key={i}><InlineMarkdown text={text}/></h4>);return}if(/^[-*+]\s/.test(t)){if(listType!=="ul"){flushList();listType="ul"}list.push(t.slice(2));return}const num=t.match(/^\d+[.)]\s/);if(num){if(listType!=="ol"){flushList();listType="ol"}list.push(t.slice(num[0].length));return}flushList();if(/^---+$/.test(t)){out.push(<hr key={i}/>);return}if(t.startsWith(">")){out.push(<blockquote key={i}><InlineMarkdown text={t.slice(1).trim()}/></blockquote>);return}out.push(<p key={i}><InlineMarkdown text={t}/></p>)});
 flushList();flushTable();if(inCode)out.push(<pre key="unfinished"><code>{code.join("\n")}</code></pre>);return <div className="response-content">{out}</div>}
