 const loadChatSessions=async()=>{if(!supabaseUser||!isSupabaseConfigured())return;const {data,error}=await getSupabase().from("chat_sessions").select("id,title,context_type,video_id,updated_at,last_message_at").eq("user_id",supabaseUser.id).order("updated_at",{ascending:false});if(!error)setChatSessions(data||[]);};
 const openChatSession=async(id)=>{setChatBusy(true);try{const supabase=getSupabase();const {data:s,error:se}=await supabase.from("chat_sessions").select("id,title,context_type,video_id").eq("id",id).eq("user_id",supabaseUser.id).single();if(se)throw se;const {data:m,error:me}=await supabase.from("chat_messages").select("id,role,content,created_at,metadata").eq("session_id",id).eq("user_id",supabaseUser.id).order("created_at",{ascending:true});if(me)throw me;const hydrated=await Promise.all((m||[]).map(async msg=>{const a=Array.isArray(msg.metadata?.attachments)?msg.metadata.attachments:[];const signed=await Promise.all(a.map(async f=>{const {data}=await supabase.storage.from("trean-chat-files").createSignedUrl(f.path,3600);return {...f,url:data?.signedUrl||null};}));return {...msg,attachments:signed};}));setActiveChatSession(s);setChatMessages(hydrated);const assistantIds=(m||[]).filter(x=>x.role==="assistant").map(x=>x.id);if(assistantIds.length){const {data:src}=await supabase.from("chat_message_sources").select("message_id,citation_label,source_title,source_type,excerpt,start_seconds,end_seconds,source_url").in("message_id",assistantIds).eq("user_id",supabaseUser.id);const grouped={};(src||[]).forEach(x=>(grouped[x.message_id]??=[]).push(x));setChatSources(grouped);}else setChatSources({});setQuestion("");setActive("chat");}catch(e){say(e.message||"Could not load chat.");}finally{setChatBusy(false)}};
 const newChat=()=>{setActiveChatSession(null);setChatMessages([]);setChatSources({});setQuestion("");setSelectedVideo("");setSelectedKnowledge([]);setChatAttachments([]);setActive("chat");};
  const handleChatFiles=async(e)=>{const files=Array.from(e.target.files||[]);e.target.value="";if(!files.length)return;if(!supabaseUser){setScreen("auth");setAuthMode("Sign In");say("Sign in to upload files.");return;}const allowed=["image/jpeg","image/png","image/webp","image/gif","application/pdf","text/plain","text/markdown","audio/mpeg","audio/mp4","audio/wav","audio/webm","audio/ogg","video/mp4","video/webm"];const current=chatAttachments.length;for(const file of files){if(current>=4){say("A message can include up to 4 files.");break;}if(!allowed.includes(file.type)){say("Supported: images, PDF, text, audio and video.");continue;}if(file.size>10*1024*1024){say(file.name+" is larger than 10 MB.");continue;}try{const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,"_").slice(0,100);const path=supabaseUser.id+"/"+crypto.randomUUID()+"_"+safeName;const {error}=await getSupabase().storage.from("trean-chat-files").upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;setChatAttachments(prev=>prev.length<4?[...prev,{path,name:file.name,mime_type:file.type,preview:file.type.startsWith("image/")?URL.createObjectURL(file):null}]:prev);say(file.name+" attached.");}catch(err){say(err.message||"File upload failed.");}}};
  const removeChatAttachment=async(path)=>{const target=chatAttachments.find(a=>a.path===path);if(target?.preview)URL.revokeObjectURL(target.preview);setChatAttachments(prev=>prev.filter(a=>a.path!==path));if(path&&supabaseUser)await getSupabase().storage.from("trean-chat-files").remove([path]);};
  const deleteChatSession=async(id)=>{if(!supabaseUser)return;const {error}=await getSupabase().from("chat_sessions").delete().eq("id",id).eq("user_id",supabaseUser.id);if(error){say(error.message);return;}setChatSessions(prev=>prev.filter(x=>x.id!==id));if(activeChatSession?.id===id)newChat();say("Chat deleted.");};
 const sendChatMessage=async(e)=>{e.preventDefault();const message=question.trim()||(chatAttachments.length?"Please analyze the attached file(s) and explain the important information.":"");if(!message||chatBusy)return;if(!supabaseUser){setScreen("auth");setAuthMode("Sign In");say("Sign in to chat with TREAN AI.");return;}setChatBusy(true);setQuestion("");setChatMessages(m=>[...m,{id:"local-"+Date.now(),role:"user",content:message,attachments:chatAttachments},{id:"pending-"+Date.now(),role:"assistant",content:"",pending:true}]);try{if(!chatAttachments.length&&/^(learn|research|study|master|deep dive|teach yourself|explore)\\b/i.test(message)){const {data:task,error:taskError}=await getSupabase().functions.invoke("create-learning-task",{body:{title:message.slice(0,180),instruction:message,scope:{sources:["youtube","web","documentation"],autonomous:true}}});if(taskError)throw taskError;if(task?.error)throw new Error(task.error);const answer="\u{1F9E0} **Background learning task started**\\n\\n"+task.message+"\\n\\n**Task:** "+task.task.title+"\\n\\nI will research the topic using web-grounded sources and build searchable knowledge. This task is saved on the backend, so you can close the browser. Progress and results will be available in your Learning Tasks.";setChatMessages(m=>m.filter(x=>!x.pending).concat({id:"task-"+task.task.id,role:"assistant",content:answer,created_at:new Date().toISOString()}));setQuestion("");return;}const request=getSupabase().functions.invoke("trean-chat",{body:{message,session_id:activeChatSession?.id||undefined,video_id:selectedVideo||activeChatSession?.video_id||undefined,context_type:selectedVideo?"video":selectedKnowledge.length?"knowledge_base":"general",knowledge_ids:selectedKnowledge,attachments:chatAttachments.map(({path,name,mime_type})=>({path,name,mime_type}))}});const timeout=new Promise((_,reject)=>setTimeout(()=>reject(new Error("TREAN AI response timed out after 35 seconds. Please try again.")),35000));const {data,error}=await Promise.race([request,timeout]);if(error)throw error;if(data?.error)throw new Error(data.error);setActiveChatSession(prev=>prev?prev:{id:data.session_id,title:message.slice(0,80),context_type:selectedVideo?"video":selectedKnowledge.length?"knowledge_base":"general",video_id:selectedVideo||null});setChatMessages(m=>m.filter(x=>!x.pending).map(x=>x.id?.startsWith("local-")?{...x,id:data.user_message_id}:x).concat({id:data.assistant_message_id,role:"assistant",content:data.answer,created_at:new Date().toISOString()}));setChatSources(prev=>({...prev,[data.assistant_message_id]:data.sources||[]}));chatAttachments.forEach(a=>{if(a.preview)URL.revokeObjectURL(a.preview)});setChatAttachments([]);await loadChatSessions();}catch(err){setChatMessages(m=>m.filter(x=>!x.pending).concat({id:"error-"+Date.now(),role:"assistant",content:"I could not complete that response. "+(err?.message||"Please try again."),error:true}));setQuestion(message);say(err.message||"Chat request failed.");}finally{setChatBusy(false)}};
 useEffect(()=>{if((active==="chat"||active==="history"||active==="sources")&&supabaseUser)loadChatSessions();if(active==="learn"&&supabaseUser)refreshLearningTasks();},[active,supabaseUser]);
 const refreshLearningTasks=async()=>{if(!supabaseUser)return;const {data,error}=await getSupabase().from("learning_tasks").select("id,title,status,progress,stage,sources_discovered,sources_processed,knowledge_items_created,result_summary,error,created_at").eq("user_id",supabaseUser.id).order("created_at",{ascending:false}).limit(30);if(!error)setLearningTasks(data||[]);};
 const refreshData=async()=>{if(!supabaseUser)return;const sb=getSupabase();const [{data:v,error:ve},{data:k,error:ke},{data:p,error:pe}]=await Promise.all([sb.from("videos").select("id,title,channel_name,thumbnail_url,youtube_url,status,duration_seconds,created_at,processing_stage,processing_progress,last_error").eq("user_id",supabaseUser.id).order("created_at",{ascending:false}),sb.from("knowledge_items").select("id,title,content,knowledge_type,video_id,created_at").eq("user_id",supabaseUser.id).order("created_at",{ascending:false}),sb.from("video_playlists").select("id,title,channel_name,thumbnail_url,total_videos,status,created_at").eq("user_id",supabaseUser.id).order("created_at",{ascending:false})]);if(!ve)setVideos(v||[]);if(!ke)setKnowledge(k||[]);if(!pe)setPlaylists(p||[]);};
 const learnAnyContent=async(e)=>{e.preventDefault();if(!supabaseUser){setScreen("auth");setAuthMode("Sign In");say("Sign in to train TREAN AI.");return;}if(!learningText.trim()&&!learningFile){say("Add text or choose a file.");return;}setLearningBusy(true);try{let path=null;if(learningFile){if(learningFile.size>25*1024*1024)throw new Error("Files must be under 25 MB.");const safe=learningFile.name.replace(/[^a-zA-Z0-9._-]/g,"_").slice(0,100);path=supabaseUser.id+"/"+crypto.randomUUID()+"_"+safe;const {error}=await getSupabase().storage.from("trean-chat-files").upload(path,learningFile,{contentType:learningFile.type,upsert:false});if(error)throw error;}const {data,error}=await getSupabase().functions.invoke("learn-content",{body:{title:learningTitle||learningFile?.name||"Personal learning material",source_type:learningFile?.type||"text",content:learningText,path,mime_type:learningFile?.type}});if(error)throw error;if(data?.error)throw new Error(data.error);setLearningTitle("");setLearningText("");setLearningFile(null);if(learningFileInput.current)learningFileInput.current.value="";await refreshData();say("TREAN learned "+data.knowledge_items+" knowledge items. AI Chat can now use this knowledge.");}catch(err){say(err.message||"Learning failed.");}finally{setLearningBusy(false)}};
 const addVideo=async(e)=>{
  e.preventDefault();
  if(!supabaseUser){setScreen("auth");setAuthMode("Sign In");say("Sign in before saving a video.");return}
  let videoId=null;try{const parsed=new URL(url.trim());if(parsed.hostname==="youtu.be")videoId=parsed.pathname.split("/").filter(Boolean)[0];else if(parsed.hostname.endsWith("youtube.com"))videoId=parsed.searchParams.get("v")||parsed.pathname.split("/").filter(Boolean).find((part,i,arr)=>["embed","shorts","live"].includes(arr[i-1]));}catch{} const match=videoId&&/^[A-Za-z0-9_-]{11}$/.test(videoId)?[url,videoId]:null;
  if(!match){say("Enter a valid YouTube video URL.");return}
  setAuthBusy(true);
  try{
   const supabase=getSupabase();
   const {data:meta,error:metaError}=await supabase.functions.invoke("youtube-metadata",{body:{url:url.trim()}});
   if(metaError)throw metaError;if(meta?.error)throw new Error(meta.error);
   const v=meta.video;
   const {data,error}=await supabase.from("videos").insert({user_id:supabaseUser.id,youtube_video_id:v.youtube_video_id,youtube_url:v.youtube_url,title:v.title,channel_name:v.channel_name,thumbnail_url:v.thumbnail_url,duration_seconds:v.duration_seconds,status:"pending"}).select().single();
   if(error)throw error;
   setVideos(x=>[data,...x]);setUrl("");say("Video saved. Processing has started…");supabase.functions.invoke("process-video",{body:{video_id:data.id}}).then(({data:result,error:workerError})=>{if(workerError||result?.error)say("Video saved, but processing failed to start. Check processing status and retry.");else if(result?.success)say("Video processing completed successfully.");}).catch(()=>say("Video saved. Processing will retry automatically if the worker is unavailable."));
  }catch(err){say(err.message||"Could not fetch YouTube video. Check API configuration and video URL.")}
  finally{setAuthBusy(false)}
 };
 const addPlaylist=async(e)=>{
   e.preventDefault();if(!supabaseUser){setScreen("auth");setAuthMode("Sign In");say("Sign in before importing a playlist.");return;}
   let playlistId="";try{const parsed=new URL(playlistUrl.trim());playlistId=parsed.searchParams.get("list")||"";}catch{}
   if(!/^[A-Za-z0-9_-]{10,80}$/.test(playlistId)){say("Paste a valid YouTube playlist URL containing list=...");return;}
   setPlaylistBusy(true);
   try{
    const {data:meta,error:metaError}=await getSupabase().functions.invoke("youtube-metadata",{body:{playlistId}});
    if(metaError)throw metaError;if(meta?.error)throw new Error(meta.error);
    const p=meta.playlist,videosInPlaylist=Array.isArray(meta.videos)?meta.videos:[];
    if(!videosInPlaylist.length)throw new Error("No importable videos were found in this playlist.");
    const {data:playlist,error:playlistError}=await getSupabase().from("video_playlists").upsert({user_id:supabaseUser.id,youtube_playlist_id:p.id,title:p.title,channel_name:p.channel_name,thumbnail_url:p.thumbnail_url,total_videos:p.total_videos,status:"processing"},{onConflict:"user_id,youtube_playlist_id"}).select("id").single();
    if(playlistError)throw playlistError;
    const rows=videosInPlaylist.map(v=>({user_id:supabaseUser.id,youtube_video_id:v.youtube_video_id,youtube_url:v.youtube_url,title:v.title,channel_name:v.channel_name,thumbnail_url:v.thumbnail_url,duration_seconds:v.duration_seconds,status:"pending"}));
    const {error:videoError}=await getSupabase().from("videos").upsert(rows,{onConflict:"user_id,youtube_video_id",ignoreDuplicates:true});if(videoError)throw videoError;
    const ids=videosInPlaylist.map(v=>v.youtube_video_id);
    const {data:savedVideos,error:lookupError}=await getSupabase().from("videos").select("id,youtube_video_id").eq("user_id",supabaseUser.id).in("youtube_video_id",ids);if(lookupError)throw lookupError;
    const order=new Map(videosInPlaylist.map((v,i)=>[v.youtube_video_id,i]));
    const links=(savedVideos||[]).map(v=>({playlist_id:playlist.id,video_id:v.id,user_id:supabaseUser.id,position:order.get(v.youtube_video_id)??0}));
    if(links.length){const {error:linkError}=await getSupabase().from("video_playlist_items").upsert(links,{onConflict:"playlist_id,video_id",ignoreDuplicates:true});if(linkError)throw linkError;}
    await getSupabase().from("video_playlists").update({status:"active",total_videos:links.length,updated_at:new Date().toISOString()}).eq("id",playlist.id).eq("user_id",supabaseUser.id);
    const {data:refreshed}=await getSupabase().from("videos").select("id,title,channel_name,thumbnail_url,youtube_url,status,duration_seconds,created_at,processing_stage,processing_progress,last_error").eq("user_id",supabaseUser.id).order("created_at",{ascending:false});
    if(refreshed)setVideos(refreshed);setPlaylists(prev=>[{id:playlist.id,title:p.title,channel_name:p.channel_name,thumbnail_url:p.thumbnail_url,total_videos:links.length,status:"active"},...prev.filter(x=>x.id!==playlist.id)]);setPlaylistUrl("");say("Imported "+links.length+" playlist videos. Background processing is queued.");
   }catch(err){say(err.message||"Playlist import failed.");}
   finally{setPlaylistBusy(false);}
  };
